    private void btnCalcularActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCalcularActionPerformed
        // Variables de estado para registrar trazabilidad en el bloque finally
        String estadoOperacion = "ERROR";
        double montoCalculado = 0.0;
        
        try {
            // 1. Lectura de campos GUI y conversión (Puede lanzar NumberFormatException)
            String strTotal = txtTotal.getText().trim();
            String strPorcentaje = txtPorcentaje.getText().trim();

            double total = Double.parseDouble(strTotal);
            double porcentaje = Double.parseDouble(strPorcentaje);

            // 2. Validación de reglas de negocio (Lanzamiento explícito de excepciones)
            if (total == 0) {
                throw new ArithmeticException("La cantidad total (100%) no puede ser cero.");
            }
            if (total < 0 || porcentaje < 0) {
                throw new IllegalArgumentException("No se permiten valores negativos.");
            }

            // 3. Procesamiento del cálculo (Ej. 30% de 32,000 = 9,600)
            montoCalculado = (total * porcentaje) / 100.0;
            double proporcion = (montoCalculado / total) * 100.0;

            // 4. Despliegue de resultados en la interfaz gráfica
            lblResultado.setForeground(new java.awt.Color(0, 102, 51));
            lblResultado.setText(String.format("Resultado: $%.2f (%.1f%%)", montoCalculado, proporcion));
            estadoOperacion = "EXITOSO";
        } catch (NumberFormatException ex) {
            // Captura entradas vacías, letras o símbolos no numéricos
            lblResultado.setForeground(java.awt.Color.RED);
            lblResultado.setText("Error: Formato numérico inválido.");
            javax.swing.JOptionPane.showMessageDialog(this,
                    "Ingrese únicamente valores numéricos válidos en ambos campos.\nDetalle: " + ex.getMessage(),
                    "Error de Entrada",
                    javax.swing.JOptionPane.ERROR_MESSAGE);
        } catch (ArithmeticException ex) {
            // Captura específica para cantidad total igual a cero
            lblResultado.setForeground(java.awt.Color.RED);
            lblResultado.setText("Error aritmético: " + ex.getMessage());
            javax.swing.JOptionPane.showMessageDialog(this,
                    ex.getMessage(),
                    "Error Matemático",
                    javax.swing.JOptionPane.WARNING_MESSAGE);
        } catch (IllegalArgumentException ex) {
            // Captura valores negativos fuera de regla de negocio
            lblResultado.setForeground(java.awt.Color.RED);
            lblResultado.setText("Error de validación: " + ex.getMessage());
            javax.swing.JOptionPane.showMessageDialog(this,
                    ex.getMessage(),
                    "Dato Fuera de Rango",
                    javax.swing.JOptionPane.WARNING_MESSAGE);
        } catch (Exception ex) {
            // Captura general de respaldo ante cualquier falla imprevista
            lblResultado.setForeground(java.awt.Color.RED);
            lblResultado.setText("Error inesperado en el sistema.");

        } finally {
            // 5. BLOQUE FINALLY: Se ejecuta SIEMPRE, ocurra o no una excepción.
            // Garantiza la actualización de la bitácora y devuelve el foco al primer campo.
            //txtBitacora.append("Operación [" + estadoOperacion + "] -> Monto: $"
              //      + String.format("%.2f", montoCalculado) + "\n");
            //txtTotal.requestFocus();
        }
    }//GEN-LAST:event_btnCalcularActionPerformed

    private void btnLimpiarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimpiarActionPerformed
        txtTotal.setText("");
        txtPorcentaje.setText("");
        lblResultado.setForeground(java.awt.Color.BLACK);
        lblResultado.setText("Resultado: $0.00");
        txtTotal.requestFocus();
    }//GEN-LAST:event_btnLimpiarActionPerformed

